function rowsOf(nodeName) {
  const root = $(nodeName).first()?.json ?? {};
  if (Array.isArray(root)) return root;
  if (Array.isArray(root.data)) return root.data;
  if (Array.isArray(root.items)) return root.items;
  if (Array.isArray(root.results)) return root.results;
  return [];
}
function contentId(row) {
  return String(row.content_id ?? row.contentId ?? row.video_id ?? row.videoId ?? row.contentID ?? row.id ?? '');
}
function competitorId(row) {
  return row.competitor_id ?? row.competitorId ?? row.competitor?.id ?? null;
}
function competitorName(row) {
  return String(row.competitor_name ?? row.competitorName ?? row.name ?? row.competitor?.name ?? 'Unknown competitor');
}
function toNum(v) {
  const n = Number(v ?? 0);
  return Number.isFinite(n) ? n : 0;
}

const trends = rowsOf('02 - Get Trends');
const analyses = rowsOf('03 - Get Content Analysis');
const contents = rowsOf('04 - Get Competitor Contents');
const metrics = rowsOf('05 - Get Performance Data');
const competitorRows = rowsOf('06 - Get Competitors');
if (!trends.length) throw new Error('Chưa có trends. Hãy chạy WF06 thành công trước.');
const totalCompetitors = new Set(competitorRows.map(c => String(c.id ?? c.competitor_id ?? c.competitorId ?? c.name ?? '')).filter(Boolean)).size || new Set(contents.map(c => String(competitorId(c) ?? '')).filter(Boolean)).size;
const contentById = new Map();
for (const c of contents) { if (contentId(c)) contentById.set(contentId(c), c); if (c.id != null) contentById.set(String(c.id), c); }
const metricById = new Map(metrics.map(m => [contentId(m), m]));
const results = [];
for (const trend of trends) {
  const topic = String(trend.name ?? trend.topic ?? trend.title ?? '').trim();
  if (!topic) continue;
  const matched = analyses.filter(a => String(a.topic ?? a.name ?? a.category ?? '').trim().toLowerCase() === topic.toLowerCase());
  const compSet = new Set();
  const evidence = [];
  let views = 0, likes = 0, comments = 0, contentVolume = 0;
  for (const a of matched) {
    const aid = String(a.content_id ?? a.contentId ?? a.id ?? '');
    const c = contentById.get(aid) ?? a;
    const cid = contentId(c) || aid;
    if (cid) evidence.push(cid);
    const comp = competitorId(c) ?? competitorId(a);
    if (comp != null) compSet.add(String(comp));
    const m = metricById.get(cid) ?? {};
    views += toNum(m.views ?? c.views);
    likes += toNum(m.likes ?? c.likes);
    comments += toNum(m.comments ?? c.comments);
    contentVolume++;
  }
  const coverageCount = compSet.size;
  const coveragePercent = totalCompetitors > 0 ? Number((coverageCount / totalCompetitors * 100).toFixed(2)) : null;
  const engagementRate = views > 0 ? Number(((likes + comments) / views * 100).toFixed(2)) : 0;
  const coverageStatus = coveragePercent === null ? 'unknown' : coveragePercent < 35 ? 'LOW' : coveragePercent < 65 ? 'MEDIUM' : 'HIGH';
  const payload = {
    topic, trend_score: toNum(trend.score), growth_rate: trend.growth_rate ?? null,
    direction: trend.direction ?? null, content_volume: contentVolume,
    competitor_coverage_count: coverageCount, total_competitors: totalCompetitors,
    coverage_percent: coveragePercent, coverage_status: coverageStatus,
    views, likes, comments, engagement_rate: engagementRate,
    evidence: [...new Set(evidence)].slice(0, 12), trend_id: trend.id ?? null
  };
  results.push({json:{...payload, ai_prompt:`You are an evidence-based competitive opportunity analyst. Identify a content opportunity only when audience demand/trend is meaningfully high and competitor coverage is comparatively low. Do not invent evidence. Return one JSON object with keys: is_opportunity (boolean), title (string), score (integer 0-100), priority (HIGH/MEDIUM/LOW), reason (short explanation), recommended_angle (short actionable angle). A high trend score with low coverage and meaningful engagement should score higher. If coverage is unknown or evidence is insufficient, lower confidence and do not assert facts.\nDATA:\n${JSON.stringify(payload)}`}});
}
if (!results.length) throw new Error('Không tạo được context từ trends.');
return results;

function parseAI(value) {
  if (value && typeof value === 'object') return value;
  if (typeof value === 'string') return JSON.parse(value.trim().replace(/^```json\s*/i,'').replace(/^```\s*/i,'').replace(/\s*```$/i,'').trim());
  throw new Error('AI Opportunity Agent không trả về JSON.');
}
const aiItems = $input.all();
const baseItems = $('07 - Build Opportunity Context').all();
return aiItems.map((item, i) => {
  const b = baseItems[i]?.json;
  if (!b) throw new Error(`Không tìm thấy opportunity context tại index ${i}`);
  const root = item.json;
  const txt =
  root.content?.parts?.[0]?.text ??
  root.output?.[0]?.content?.[0]?.text ??
  root.output?.[0]?.content?.text ??
  root.text ??
  root.message?.content;
  const a = parseAI(txt);
  const score = Math.round(Math.max(0, Math.min(100, Number(a.score ?? 0))));
  const priority = ['HIGH','MEDIUM','LOW'].includes(String(a.priority ?? '').toUpperCase()) ? String(a.priority).toUpperCase() : (score >= 80 ? 'HIGH' : score >= 60 ? 'MEDIUM' : 'LOW');
  return {json:{title:String(a.title ?? `${b.topic} Opportunity`), score, priority, reason:String(a.reason ?? 'Đánh giá theo trend, competitor coverage và engagement.'), evidence:[...(b.trend_id != null ? [`trend_${b.trend_id}`] : []), ...b.evidence].slice(0,15), recommended_angle:String(a.recommended_angle ?? ''), topic:b.topic, trend_score:b.trend_score, coverage_status:b.coverage_status, coverage_percent:b.coverage_percent, engagement_rate:b.engagement_rate, created_at:new Date().toISOString(), is_opportunity:a.is_opportunity === true && score >= 50 && b.coverage_status !== 'HIGH'}};
});
